Color? _restageA2uiColor(String? value) {
  if (value == null || value.isEmpty) return null;
  final normalized = value.startsWith('#')
      ? value.substring(1)
      : value.startsWith('0x')
      ? value.substring(2)
      : value;
  final parsed = int.tryParse(normalized, radix: 16);
  if (parsed == null) return null;
  if (normalized.length <= 6) return Color(0xFF000000 | parsed);
  return Color(parsed);
}

FontWeight _restageA2uiFontWeight(num? value, FontWeight fallback) {
  if (value == null) return fallback;
  final index = value.toInt();
  if (index < 0 || index >= FontWeight.values.length) {
    return fallback;
  }
  return FontWeight.values[index];
}

T? _restageA2uiAs<T>(Object? v) => v is T ? v : null;

Map<String, V>? _restageA2uiMap<V>(Object? raw, V? Function(Object?) coerce) {
  if (raw is! Map) return null;
  final result = <String, V>{};
  for (final entry in raw.entries) {
    final key = entry.key;
    if (key is! String) continue;
    final value = coerce(entry.value);
    if (value == null) continue;
    result[key] = value;
  }
  return result;
}

