p5.Product? _restageA2uiBuild_Product(Object? _raw, int _depth) {
  if (_depth > _kA2uiMaxBuildDepth) return null;
  if (_raw is! Map<String, Object?>) return null;
  final name = _restageA2uiAs<String>(_raw['name']);
