      .toList();
  if (features == null) return null;
  final attributes = _restageA2uiMap<String>(
    _raw['attributes'],
    (v) => _restageA2uiAs<String>(v),
  );
  if (attributes == null) return null;
  final size = _restageA2uiAs<Map<String, Object?>>(_raw['size']) == null
      ? null
      : (
          height:
              _restageA2uiAs<num>(
                _restageA2uiAs<Map<String, Object?>>(_raw['size'])?['height'],
